    check_dict_case({"Name":"John", "Age":"36", "City":"Houston"}) should return False.
    check_dict_case({"STATE":"NC", "ZIP":"12345" }) should return True.
    """
    if not dict:
        return False

    keys = list(dict.keys())

    for key in keys:
        if not isinstance(key, str):
            return False

    if not keys:
        return False

    first_key_lower = keys[0].islower()
    first_key_upper = keys[0].isupper()

    if first_key_lower:
        for key in keys[1:]:
            if not key.islower():
                return False
    elif first_key_upper:
        for key in keys[1:]:
            if not key.isupper():
                return False
    else:
        return False

    return True
